/**
 * Compare table — Phase 2 Package D (req 4), GM Portal's "Compare" action.
 *
 * A plain table: Original Agreement / Revised Agreement with Amendment /
 * Generated by Whom, covering every filled-in field value plus any formal
 * clause revisions on this agreement. Deliberately separate from
 * AgreementCompare.tsx (the existing side-by-side PDF + inline track-
 * changes view used by other roles) — this is the simpler, table-only
 * view GM uses.
 *
 * 2026-08-26 client feedback: every ROW gets its own independent decision
 * (Approve / Approve with comments / Reject with comments), not one action
 * for the whole page — "a decision action for every change ... not for
 * all the changes." The agreement's overall review step isn't resolved
 * until every row has a decision; once it is, the backend
 * (finalize-check) aggregates automatically: any rejection sends the
 * agreement back to Admin, all-approved finishes the reviewer's step.
 * "field" rows post to the new per-field decision endpoint; "clause_revision"
 * rows reuse the existing accept/reject endpoints unchanged. Either way,
 * a finalize-check call follows every decision.
 */
import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

import { useToast } from "../components/Toast";
import { humanRole } from "../lib/roles";
import { api } from "../lib/api";
import { useAuth } from "../stores/auth";

type CompareRow = {
  id: string;
  kind: "field" | "clause_revision";
  field_id: string | null;
  clause_label: string;
  original_text: string;
  revised_text: string;
  change_reason: string | null;
  status: string;
  decision_status: "pending" | "approved" | "rejected";
  decision_comment: string | null;
  decided_by_name: string | null;
  generated_by_name: string | null;
  generated_by_role: string | null;
  created_at: string | null;
};

type WorkflowStep = {
  id: string;
  step_name: string;
  step_order: number;
  role_required: string;
  status: string;
};

const DECISION_STYLES: Record<string, string> = {
  approved: "bg-green-100 text-green-700 border-green-300",
  pending: "bg-amber-100 text-amber-700 border-amber-300",
  rejected: "bg-red-100 text-red-700 border-red-300",
};

const isResolutionStepName = (name: string) => name.startsWith("Resolution");

type RowUiState = { open: boolean; comment: string; busy: boolean };

export default function AgreementCompareTable() {
  const { id: agreementId } = useParams<{ id: string }>();
  const toast = useToast();
  const role = useAuth((s) => s.user?.role);

  const [rows, setRows] = useState<CompareRow[]>([]);
  const [steps, setSteps] = useState<WorkflowStep[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [rowState, setRowState] = useState<Record<string, RowUiState>>({});

  const load = async () => {
    if (!agreementId) return;
    setLoading(true);
    setError(null);
    try {
      const [compareResp, summaryResp] = await Promise.all([
        api.get(`/agreements/${agreementId}/compare-table`),
        api.get(`/workflow/agreements/${agreementId}`),
      ]);
      setRows(compareResp.data.rows ?? []);
      setSteps(summaryResp.data.steps ?? []);
    } catch {
      setError("Failed to load the compare table.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [agreementId]);

  const myStep = steps.find((s) => s.role_required === role) ?? null;
  const myStepChainSteps = steps.filter(
    (s) => isResolutionStepName(s.step_name) === (myStep ? isResolutionStepName(myStep.step_name) : false)
  );
  const priorStep = myStep ? myStepChainSteps.find((s) => s.step_order === myStep.step_order - 1) : null;
  const myStepUnlocked = !myStep || myStep.step_order <= 1 || priorStep?.status === "approved";
  const canDecide = role !== "admin" && !!myStep && myStep.status === "pending" && myStepUnlocked;

  const getRowState = (id: string): RowUiState => rowState[id] ?? { open: false, comment: "", busy: false };
  const setRowStateFor = (id: string, patch: Partial<RowUiState>) =>
    setRowState((s) => ({ ...s, [id]: { ...getRowState(id), ...patch } }));

  const decideRow = async (row: CompareRow, decision: "approved" | "rejected", withComment: boolean) => {
    const st = getRowState(row.id);
    const requiresComment = withComment || decision === "rejected";
    if (requiresComment && !st.comment.trim()) {
      toast.error("Please enter a comment.");
      return;
    }
    setRowStateFor(row.id, { busy: true });
    try {
      if (row.kind === "field" && row.field_id) {
        await api.post(`/agreements/${agreementId}/compare-table/fields/${row.field_id}/decision`, {
          decision,
          comment_text: requiresComment ? st.comment.trim() : null,
        });
      } else {
        const endpoint = decision === "approved" ? "accept" : "reject";
        await api.post(`/agreements/${agreementId}/revisions/${row.id}/${endpoint}`, {
          decision_note: st.comment.trim() || null,
        });
      }

      const fin = await api.post(`/agreements/${agreementId}/compare-table/finalize-check`);
      if (fin.data.step_finalized) {
        toast.success(
          fin.data.step_result === "approved"
            ? "All items reviewed — agreement approved."
            : "Sent back to Admin for revision."
        );
      } else {
        toast.success("Decision recorded.");
      }
      setRowStateFor(row.id, { open: false, comment: "", busy: false });
      await load();
    } catch (err: unknown) {
      const e = err as { response?: { data?: { detail?: string } } };
      toast.error(e?.response?.data?.detail ?? "Failed to record decision.");
      setRowStateFor(row.id, { busy: false });
    }
  };

  return (
    <div className="p-4">
      <h1 className="mb-3 text-lg font-semibold">Compare — Original vs Revised Agreement</h1>

      {loading ? (
        <p className="text-sm text-gray-400">Loading…</p>
      ) : error ? (
        <p className="text-sm text-red-600">{error}</p>
      ) : rows.length === 0 ? (
        <p className="text-sm text-gray-400">No admin-entered content on this agreement yet.</p>
      ) : (
        <div className="overflow-auto rounded border">
          <table className="min-w-[1000px] w-full border-collapse text-sm">
            <thead>
              <tr className="bg-gray-100 text-left text-xs text-gray-600">
                <th className="border p-2 font-semibold">Clause</th>
                <th className="min-w-[200px] border p-2 font-semibold">Original Agreement</th>
                <th className="min-w-[200px] border p-2 font-semibold">Revised Agreement with Amendment</th>
                <th className="border p-2 font-semibold">Generated by Whom</th>
                <th className="min-w-[220px] border p-2 font-semibold">Decision</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const st = getRowState(row.id);
                const rowDecidable = canDecide && row.decision_status === "pending";
                return (
                  <tr key={row.id}>
                    <td className="border p-2 align-top text-xs text-gray-700">{row.clause_label}</td>
                    <td className="border p-2 align-top text-xs text-gray-500">
                      <span className="whitespace-pre-wrap break-words leading-relaxed">{row.original_text}</span>
                    </td>
                    <td className="border p-2 align-top text-xs text-gray-900">
                      <span className="whitespace-pre-wrap break-words leading-relaxed font-medium">
                        {row.revised_text}
                      </span>
                      {row.change_reason && (
                        <div className="mt-1 text-[11px] italic text-gray-500">Reason: {row.change_reason}</div>
                      )}
                    </td>
                    <td className="border p-2 align-top text-xs text-gray-700">
                      {row.generated_by_name ?? "Unknown"}
                      {row.generated_by_role && (
                        <div className="text-[11px] text-gray-400">{humanRole(row.generated_by_role)}</div>
                      )}
                    </td>
                    <td className="border p-2 align-top text-xs">
                      {!rowDecidable ? (
                        <div>
                          <span
                            className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold capitalize ${
                              DECISION_STYLES[row.decision_status] ?? "bg-gray-100 text-gray-600 border-gray-300"
                            }`}
                          >
                            {row.decision_status}
                          </span>
                          {row.decision_comment && (
                            <div className="mt-1 text-[11px] text-gray-600">"{row.decision_comment}"</div>
                          )}
                          {row.decided_by_name && (
                            <div className="mt-0.5 text-[10px] text-gray-400">by {row.decided_by_name}</div>
                          )}
                        </div>
                      ) : !st.open ? (
                        <button
                          className="rounded border border-sky-300 bg-sky-50 px-2 py-1 text-[11px] font-medium text-sky-800 hover:bg-sky-100"
                          onClick={() => setRowStateFor(row.id, { open: true })}
                        >
                          Decide
                        </button>
                      ) : (
                        <div className="space-y-1.5">
                          <textarea
                            className="w-full rounded border p-1.5 text-[11px]"
                            rows={2}
                            placeholder="Comment (required for 'with comments' / reject)"
                            value={st.comment}
                            onChange={(e) => setRowStateFor(row.id, { comment: e.target.value })}
                            disabled={st.busy}
                          />
                          <div className="flex flex-wrap gap-1">
                            <button
                              className="rounded bg-green-600 px-2 py-1 text-[10px] font-medium text-white disabled:opacity-50"
                              disabled={st.busy}
                              onClick={() => decideRow(row, "approved", false)}
                            >
                              Approve
                            </button>
                            <button
                              className="rounded bg-green-100 px-2 py-1 text-[10px] font-medium text-green-800 disabled:opacity-50"
                              disabled={st.busy}
                              onClick={() => decideRow(row, "approved", true)}
                            >
                              Approve w/ comments
                            </button>
                            <button
                              className="rounded bg-red-100 px-2 py-1 text-[10px] font-medium text-red-800 disabled:opacity-50"
                              disabled={st.busy}
                              onClick={() => decideRow(row, "rejected", true)}
                            >
                              Reject w/ comments
                            </button>
                            <button
                              className="rounded border px-2 py-1 text-[10px] text-gray-500 disabled:opacity-50"
                              disabled={st.busy}
                              onClick={() => setRowStateFor(row.id, { open: false })}
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
